Running command: cd /workspace && cat > test_tga2.cpp << 'EOF'
#include <QImage>
#include <QBuffer>
#include <QDebug>
#include <cstdio>
#include <cstdlib>
#include <cstring>

// Include the TGA handler directly
#include "tga_p.h"

int main(int argc, char **argv) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <tga_file>\n", argv[0]);
        return 1;
    }

    FILE *f = fopen(argv[1], "rb");
    if (!f) { perror("fopen"); return 1; }
    fseek(f, 0, SEEK_END);
    long sz = ftell(f);
    fseek(f, 0, SEEK_SET);

    char *buf = new char[sz];
    size_t nread = fread(buf, 1, sz, f);
    fclose(f);

    fprintf(stderr, "Read %zu bytes from %s\n", nread, argv[1]);

    QBuffer b;
    b.setData(buf, sz);
    b.open(QIODevice::ReadOnly);

    TGAHandler handler;
    handler.setDevice(&b);

    QImage img;
    bool ok = handler.read(&img);

    fprintf(stderr, "Read result: %s\n", ok ? "true" : "false");

    delete[] buf;
    return ok ? 0 : 1;
}
EOF

